<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {api,mutate,can,text,date,opts,useTask,type DTO,type Page} from './shared';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';
const route=useRoute(),{busy,error,notice,run}=useTask(),{form,open}=useForm(),rows=ref<DTO<'Stage2ConnectionView'>[]>([]),selected=ref<DTO<'Stage2ConnectionView'>>(),jobs=ref<DTO<'Stage2JobView'>[]>([]),snapshots=ref<DTO<'Stage2SnapshotView'>[]>([]),providers=ref<DTO<'Stage2ProviderCapability'>[]>([]),worker=ref<DTO<'Stage2WorkerStatus'>>(),page=ref(1),total=ref(0),more=ref(false),jobPage=ref(1),jobTotal=ref(0),jobMore=ref(false),snapshotPage=ref(1),snapshotTotal=ref(0),snapshotMore=ref(false);let timer:ReturnType<typeof setTimeout>;
const safeErrors:Record<string,string>={CREDENTIAL_UNAVAILABLE:'凭据不可用，请检查凭据状态与版本',UPSTREAM_UNAUTHORIZED:'平台拒绝认证，请检查 API Key',UPSTREAM_RATE_LIMITED:'平台限流，任务会按规则重试',UPSTREAM_TIMEOUT:'平台响应超时',UPSTREAM_UNAVAILABLE:'平台暂不可用',INVALID_PROVIDER_RESPONSE:'平台响应未通过校验',CONNECTION_INACTIVE:'连接已暂停'};
async function detail(){if(!selected.value)return;const suffix='&connection_id='+selected.value.id;const result=await Promise.allSettled([api.get<Page<DTO<'Stage2JobView'>>>('/sync-jobs?page='+jobPage.value+suffix),...(can('finance.read')?[api.get<Page<DTO<'Stage2SnapshotView'>>>('/metric-snapshots?page='+snapshotPage.value+suffix)]:[])]);for(let i=0;i<result.length;i++){const r=result[i];if(r.status==='rejected')throw r.reason;if(i===0){jobs.value=r.value.items as DTO<'Stage2JobView'>[];jobTotal.value=r.value.pagination.total;jobMore.value=r.value.pagination.has_next;}else{snapshots.value=r.value.items as DTO<'Stage2SnapshotView'>[];snapshotTotal.value=r.value.pagination.total;snapshotMore.value=r.value.pagination.has_next;}}}
async function load(){await run(async()=>{const data=await api.get<Page<DTO<'Stage2ConnectionView'>>>('/platform-connections?page='+page.value);rows.value=data.items;total.value=data.pagination.total;more.value=data.pagination.has_next;if(selected.value)selected.value=rows.value.find(r=>r.id===selected.value?.id)??selected.value;if(!selected.value&&route.query.connection)selected.value=rows.value.find(r=>r.id===route.query.connection);await detail();if(can('identity.manage'))worker.value=await api.get<DTO<'Stage2WorkerStatus'>>('/integration-worker');});}
function edit(c?:DTO<'Stage2ConnectionView'>){open({title:c?'维护平台连接':'新增平台连接',description:'首批支持 DeepSeek 账号级余额，不支持逐 Key 用量、Token 数或模型消耗。连接只引用资源中已保存的凭据。',fields:[...(!c?[{key:'resource_id',label:'所属资源',required:true,endpoint:'/resources'}]:[]),{key:'label',label:'连接名称',required:!c,initial:c?.label},{key:'credential_id',label:'有效 API Key 凭据',required:true,endpoint:(v:Record<string,string>)=>(c?.resource_id||v.resource_id)?`/resources/${c?.resource_id??v.resource_id}/credentials`:'',initial:c?.credential_id},{key:'scheduled',label:'定时同步',required:true,options:[{value:'false',label:'手动同步'},{value:'true',label:'启用定时同步'}],initial:String(c?.scheduled??false)},{key:'interval_seconds',label:'同步间隔（秒）',type:'number',required:true,min:3600,max:604800,initial:String(c?.interval_seconds??21600)},...(c?[{key:'status',label:'连接状态',options:opts(['active','inactive']),initial:c.status}]:[])],onSubmit:async v=>{const body={credential_id:v.credential_id,scheduled:v.scheduled==='true',interval_seconds:Number(v.interval_seconds),...(c?{expected_version:c.version,status:v.status}:{label:v.label,resource_id:v.resource_id,provider:'deepseek'})};await mutate(c?'/platform-connections/'+c.id:'/platform-connections',body,c?'PATCH':'POST');await load();}});}
async function trigger(c:DTO<'Stage2ConnectionView'>,action:string){await run(async()=>{await mutate(`/platform-connections/${c.id}/actions/${action}`);selected.value=c;notice.value='任务已排队，尚未代表平台采集成功。';await detail();clearTimeout(timer);timer=setTimeout(()=>void load(),2500);});}
onMounted(async()=>{await load();try{providers.value=(await api.get<DTO<'Stage2ProviderPage'>>('/integration-providers')).items;}catch(e){/* The main list remains usable when capability metadata is unavailable. */}});onBeforeUnmount(()=>clearTimeout(timer));
</script>
<template><div class="toolbar justify-between"><p class="text-xs text-gray-500">DeepSeek · 账号余额 · 单位为币种金额；不等同逐 Key 用量。</p><div class="flex gap-2"><button class="btn-secondary" :disabled="busy" @click="load">刷新状态</button><button v-if="can('integration.manage')" class="btn-primary" @click="edit()">新增连接</button></div></div><PageState :error="error" :busy="busy" :notice="notice" :empty="!rows.length" @retry="load"/><p v-if="worker" class="mx-3 my-2 text-xs" :class="worker.recent_heartbeat?'text-emerald-700':'text-amber-700'">后台任务：{{worker.recent_heartbeat?'近期心跳正常':'未检测到近期心跳，任务可能等待处理'}} · 最近 {{date(worker.last_seen_at)}}</p><div class="admin-table-scroll"><table class="feishu-table min-w-[650px]"><thead><tr><th>连接</th><th>状态</th><th>最近成功 / 新鲜度</th><th>问题</th><th>操作</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><button class="text-link font-medium" @click="selected=c;jobPage=1;snapshotPage=1;run(detail)">{{c.label}}</button><p class="mt-1 text-gray-500">{{text(c.provider)}} · <RouterLink :to="'/resources/'+c.resource_id" class="text-link">所属资源</RouterLink></p></td><td>{{text(c.status)}}<p class="mt-1 text-gray-500">{{c.scheduled?'定时 '+c.interval_seconds+' 秒':'手动'}}</p></td><td>{{date(c.last_success_at)}}<p class="mt-1" :class="c.stale?'text-amber-700':'text-emerald-700'">{{c.stale?'数据陈旧':'近期有效'}}</p></td><td>{{c.last_error_code?safeErrors[c.last_error_code]??c.last_error_code:'—'}}</td><td><div class="flex gap-1"><button class="btn-ghost text-xs" :disabled="busy||c.status!=='active'" @click="trigger(c,'test')">测试</button><button class="btn-ghost text-xs" :disabled="busy||c.status!=='active'" @click="trigger(c,'sync')">同步</button><button class="btn-ghost text-xs" @click="edit(c)">维护</button></div></td></tr></tbody></table></div><Pager :page="page" :total="total" :more="more" @change="page=$event;load()"/><div v-if="selected" class="border-t border-gray-200 p-4"><h3 class="text-sm font-medium">{{selected.label}} · 采集记录</h3><p class="mt-1 text-xs text-gray-500">最近尝试 {{date(selected.last_attempt_at)}}；余额仅反映采集时点。</p><div v-if="can('finance.read')" class="mt-3"><h4 class="text-xs font-medium">余额快照</h4><p v-if="!snapshots.length" class="my-3 text-xs text-gray-500">尚无成功快照。排队或失败不会生成虚构余额。</p><div v-for="s in snapshots" :key="s.id" class="mt-2 rounded-lg border border-gray-200 p-3 text-sm"><strong>{{s.currency}} {{s.total_balance}}</strong><span class="ml-2 text-xs text-gray-500">{{date(s.collected_at)}} · {{s.is_available?'平台可用':'平台不可用'}}</span><p class="mt-1 text-xs text-gray-500">赠送 {{s.granted_balance}} · 充值 {{s.topped_up_balance}} · {{text(s.meaning)}}</p></div><Pager :page="snapshotPage" :total="snapshotTotal" :more="snapshotMore" @change="snapshotPage=$event;run(detail)"/></div><h4 class="mb-2 mt-4 text-xs font-medium">任务状态</h4><div v-for="j in jobs" :key="j.id" class="border-b py-2 text-xs">{{text(j.status)}} · 尝试 {{j.attempts}} 次 · {{date(j.finished_at??j.available_at)}}<p v-if="j.last_error_code" class="mt-1 text-amber-700">{{safeErrors[j.last_error_code]??j.last_error_code}}</p></div><Pager :page="jobPage" :total="jobTotal" :more="jobMore" @change="jobPage=$event;run(detail)"/></div><p v-for="p in providers" :key="p.provider" class="px-4 py-3 text-[11px] text-gray-500">平台能力依据：<a :href="p.official_documentation" target="_blank" rel="noopener noreferrer" class="text-link">官方余额接口</a> · 核对于 {{p.checked_on}}</p><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
